using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BoostHeveliusHeveliusLinkEffect", menuName = "Data/Battle/Effects/Hevelius/BoostHeveliusHeveliusLink Effect")]
public class BoostHeveliusHeveliusLinkEffect : HeveliusHeveliusLinkEffect
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(base.localizationManager.GetLocalizedAddDie(), amount) + playerEffectsList.PlayerBoostEffect.GetDieDiscardedDuringDrawPhasePurificationDescription() + GetEffectStayActiveDescription() + AppendedDescription();
	}
}
